class DeviceNotSupported(Exception):
    pass


class OpticalSwitchConnectionError(Exception):
    pass


class Timeout(OpticalSwitchConnectionError):
    pass


class TooManyRetries(OpticalSwitchConnectionError):
    pass


class OpticalSwitchError(Exception):
    pass


class OpticalSwitchResponseError(OpticalSwitchError):
    pass


class InvalidInput(OpticalSwitchError, AttributeError):
    """Set command input is incorrect"""


class OperationNotSupported(Exception):
    pass


class OpticalSwitchCommandInvalid(Exception):
    pass


class InvalidHost(Exception):
    """Invalid host, is not IP or Serial Port"""
